rules.sql:
SELECT vdate AS "日期", vno AS "凭证号", summary AS "摘要", acct_code AS "科目编码", acct_name AS "科目名称", debit AS "借方", credit AS "贷方", src AS "来源"
FROM journal
WHERE greatest(coalesce(debit,0), coalesce(credit,0)) >= {{amt}}
ORDER BY greatest(coalesce(debit,0), coalesce(credit,0)) DESC
LIMIT {{limit}}
